// Seed 67 đề Speaking Part 4 (nói về chủ đề trừu tượng) vào MongoDB.
//
// Chạy:
//   docker exec -i aptis-mongo mongosh --quiet < scripts/seed-speaking-part4.js
//   node scripts/gen-speaking-part4-sql.js
//   docker exec -i aptis-mysql mysql -uaptis -paptis --default-character-set=utf8mb4 aptis < scripts/seed-speaking-part4.sql
//
// Mỗi đề: 1 câu hỏi, chuẩn bị 60 giây rồi nói 120 giây (180–240 từ), 20 điểm.
// KHÔNG gộp câu như Part 1 — Part 4 mỗi đề là một bài nói dài độc lập.
//
// `explanation` là BÀI NÓI MẪU học viên xem tham khảo (nút "Xem câu mẫu").
// `hot` là số ngọn lửa: đề càng hay ra thi càng nhiều lửa (1-5).

const target = db.getSiblingDB('aptis');

const PART_ID = '16000000-0000-4000-8000-000000000034'; // Speaking Part 4
const TASK_TYPE = 'AUDIO_RECORDING';

const PREP_SECONDS = 60;
const RESPONSE_SECONDS = 120;
const ITEM_SCORE = 20;

// [câu hỏi tiếng Anh, dịch tiếng Việt, độ hot 1-5, bài nói mẫu]
const TOPICS = [
  ['Talk about a time you received a difficult question.',
    'Kể về một lần bạn nhận được một câu hỏi khó', 5,
    'I would like to talk about a difficult question I received during a job interview last year. The interviewer asked me to describe a situation where I had failed, and what I learned from it. At first I felt uncomfortable, because nobody enjoys talking about their mistakes, especially in an interview. I paused for a few seconds to think, then decided to be honest. I described a group project at university where I had underestimated how long the work would take, so we submitted it late. I explained that I learned to plan more carefully and to ask for help earlier instead of waiting until the deadline. Looking back, I think that was the most valuable question in the whole interview. It forced me to reflect honestly rather than repeat prepared answers. It also taught me that admitting a weakness, when you can show what you learned from it, is far stronger than pretending to be perfect. Since then I have been much more comfortable discussing my mistakes openly. I also noticed afterwards that the interviewer seemed more interested in how I reasoned than in the mistake itself. That changed how I prepare for interviews now: instead of memorising perfect answers, I think about what each experience actually taught me.'],
  ['Talk about a time you visited a friend.',
    'Kể về một lần bạn tới thăm một người bạn', 5,
    'I would like to talk about a time I visited a close friend who had moved to another city for work. We had not seen each other for almost a year, so I took a bus there one weekend. The journey took about four hours, and I remember feeling excited as I got closer. She met me at the station and we went straight to a small restaurant near her apartment. We spent the whole afternoon talking about our jobs, our families, and how much our lives had changed. In the evening she showed me around her neighbourhood, which was much quieter than where I live. What made the visit special was not any particular activity, but simply having enough time to talk properly. Messages and phone calls are convenient, but they cannot replace sitting together in the same room. I stayed two nights and returned home feeling refreshed. Since then we have agreed to visit each other at least twice a year. Since that visit we have made it a habit to alternate: one year she comes to my city, the next year I go to hers. Having something planned in the calendar makes it far more likely to actually happen, which is a lesson I have applied to other friendships too.'],
  ['Describe a time when you achieved something.',
    'Kể về một lần bạn đạt được thành tựu', 5,
    'I would like to describe the time I passed an important English examination. I had been studying for about eight months, mostly in the evenings after work, because I needed the certificate for my job application. The most difficult part was speaking, since I had few opportunities to practise with other people. To solve this, I joined an online conversation group and recorded myself answering questions every day. Some days I felt discouraged because my progress seemed very slow. When I finally received my results and saw that I had reached the level I needed, I felt genuinely proud. It was not only about the certificate itself. What mattered more was proving to myself that I could set a difficult goal and keep working towards it for months without giving up. That experience changed how I approach other challenges. Now, when something looks too difficult, I break it into small daily tasks instead of feeling overwhelmed by the whole thing. I keep the certificate in my desk drawer rather than on the wall, but I look at it occasionally when I feel stuck on something difficult. It is a useful reminder that progress which feels invisible day to day can still add up to something significant over months.'],
  ['Talk about a time you had a long trip.',
    'Kể về một lần bạn có một chuyến đi dài', 5,
    'I would like to talk about a long trip I took to the north of my country two years ago. My friends and I travelled by overnight train, which took about ten hours. We chose the train instead of flying because we wanted to see the countryside along the way. The journey itself was quite tiring, as it was difficult to sleep properly, but watching the sunrise over the mountains the next morning made it worthwhile. We stayed for four days, walking through terraced fields, visiting local markets, and trying food we had never eaten before. The weather was cooler than in my city, which was a pleasant change. What I remember most is how friendly the local people were, even though we did not speak their dialect. Long trips can be exhausting, but they give you time to disconnect from daily routines and notice things you normally ignore. I would happily make the same journey again if I had a week free. On the way home I slept for most of the journey, completely exhausted but satisfied. What surprised me afterwards was how clearly I remembered small details of that trip compared with holidays where I had simply flown somewhere and stayed in a resort.'],
  ['Talk about a time you helped someone.',
    'Kể về một lần bạn giúp đỡ ai đó', 4,
    'I would like to talk about a time I helped an elderly neighbour. She lives alone, and one afternoon I noticed her struggling to carry several heavy bags of shopping up the stairs. I offered to help and carried them to her apartment. She invited me in for tea, and we ended up talking for almost an hour about her family and how the neighbourhood had changed over the years. After that, I started checking on her once or twice a week, sometimes buying groceries for her when the weather was bad. It required very little effort from me, perhaps twenty minutes of my time, but it clearly meant a great deal to her. That experience taught me that helping people does not always require money or special skills. Often it just requires noticing that someone needs help and being willing to stop what you are doing. I think small acts like this matter more than we usually realise. What I did not expect was how much I gained from it as well. Living in a city, it is easy to know nobody in your own building. Through those short conversations I ended up feeling much more connected to the place where I live.'],
  ['Talk about a busy time you had.',
    'Kể về một lần bạn bận rộn', 4,
    'I would like to talk about a particularly busy period I had at the end of last year. I was preparing for an important examination while also finishing a project at work, and both deadlines fell in the same two weeks. I was sleeping about five hours a night and constantly felt that I was behind on everything. To manage it, I wrote a list every morning and forced myself to finish the two most important tasks before doing anything else. I also stopped checking social media, which saved more time than I expected. It was stressful, but I completed both the project and the exam, although I was exhausted afterwards. Looking back, I learned two things. First, I can handle more pressure than I thought. Second, and more importantly, I should avoid letting deadlines pile up like that again. Now I try to start earlier so that I have space when something unexpected happens. I also learned to say no more often. During that period I had agreed to several small commitments that were not important, and dropping them would have made everything easier. Now I check my calendar before agreeing to anything new.'],
  ['Describe a time when you learned a new skill.',
    'Kể về một lần bạn học một kỹ năng mới', 4,
    'I would like to describe how I learned to cook properly. Until about two years ago I relied almost entirely on instant food and restaurants, mainly because I believed cooking was complicated and time-consuming. Then I decided to change, partly to eat more healthily and partly to save money. I started with very simple dishes, following short videos online, and I made plenty of mistakes at the beginning. Some meals were far too salty and one dish I had to throw away completely. Gradually I learned the basics, such as how to control heat and how to combine flavours. Now I cook most of my meals and genuinely enjoy it. What surprised me was that cooking became a way to relax rather than another chore. This experience also taught me a general lesson about learning: starting badly is completely normal, and the only real mistake is expecting to be good immediately. These days I cook for my family at weekends, and my mother has even asked me for one of my recipes, which felt like a genuine achievement. It also saves me a considerable amount of money compared with two years ago.'],
  ['Talk about a time you had many choices.',
    'Kể về một lần bạn có nhiều sự lựa chọn', 3,
    'I would like to talk about choosing my university major, which was the first time I faced too many options. I was interested in economics, computer science, and languages, and each one seemed to offer a reasonable future. My parents preferred economics, my friends encouraged computer science, and I personally enjoyed languages the most. For several weeks I could not decide, and the more advice I received, the more confused I felt. Eventually I made a list of what mattered most to me: job opportunities, how much I would enjoy studying, and whether I could combine it with other interests. That helped me see that I did not have to choose between them completely. I studied economics but continued learning English seriously, and later that combination turned out to be useful. What I learned is that having many choices feels like freedom but is often stressful. Deciding what you truly value first makes the decision much clearer. Looking back, I am glad I did not rush the decision, but I also wish I had asked fewer people for advice. Beyond a certain point, more opinions simply made the choice harder rather than clearer.'],
  ['Talk about a time you spent a lot of time planning something.',
    'Kể về một lần bạn mất nhiều thời gian để lên kế hoạch cho một việc', 2,
    'I would like to talk about planning a surprise birthday party for my mother. I started about a month in advance because I wanted everything to be right. I had to choose a date when all our relatives were free, find a suitable restaurant, order a cake, and keep it secret from her the whole time, which was surprisingly the hardest part. I also collected old family photographs to make a small album as a gift. There were several problems along the way: the first restaurant I chose was fully booked, and two relatives changed their plans at the last minute. On the day itself, everything went smoothly and my mother was genuinely surprised and moved. Looking back, the planning took far longer than the party, which lasted only a few hours. But I do not regret the time at all. Careful planning was exactly what made the day feel special rather than ordinary. The album of old photographs turned out to be the part she liked most, even though it cost almost nothing. That taught me that thoughtfulness matters far more than money when you are preparing something for someone you love.'],
  ["Talk about a time you wanted something but couldn't get it.",
    'Kể về một lần bạn muốn thứ gì đó nhưng không có được', 3,
    'I would like to talk about a scholarship I applied for but did not receive. It was a programme that would have allowed me to study abroad for a year, and I spent almost two months preparing the application, including essays and recommendation letters. I reached the final round of interviews, so I genuinely believed I had a chance. When the results came, I was not selected, and I felt disappointed for several weeks. Looking back now, I can see two things more clearly. First, the preparation itself improved my writing and interview skills, which helped me later in job applications. Second, the reason I was rejected was that my work experience was limited, and that was fair. So instead of giving up, I focused on gaining experience. I still hope to study abroad in the future. The disappointment was real, but it gave me a clearer idea of what I actually needed to improve. I applied for a different programme the following year with much stronger experience, and although I am still waiting for the result, the application itself was far better. Failing the first time is what made the second attempt possible.'],
  ['Describe a time when you hurried to do something.',
    'Kể về một lần bạn vội vã làm gì đó', 3,
    'I would like to describe a morning when I had to rush to catch a flight. I had set my alarm the night before, but it did not go off, so I woke up only ninety minutes before departure. I packed in about ten minutes, which meant simply pushing clothes into my bag without folding anything. Traffic was heavy, and I remember constantly checking the time and feeling my heart beating quickly. I arrived at the airport just as the check-in desk was closing, and the staff let me through only because I had no luggage to check in. I did catch the flight, but I was tense for the first hour. Afterwards I discovered I had forgotten my phone charger and one shoe of a pair. Since that day I always prepare my bag the night before and set two alarms. Rushing occasionally is unavoidable, but that morning taught me it is usually the result of poor preparation. On the flight I also realised how much unnecessary stress I had created for myself over something entirely preventable. Now I treat preparation the night before as part of the journey rather than an optional extra.'],
  ['Describe a time when you helped someone.',
    'Kể về một lần bạn giúp đỡ một ai đó', 4,
    'I would like to describe a time I helped a classmate who was struggling with mathematics. We were preparing for final examinations, and he was clearly worried because he had missed several lessons due to illness. I offered to study with him twice a week, and we worked through the topics he had missed. Explaining the material to someone else turned out to be surprisingly difficult, because I realised I understood some concepts less well than I thought. In the end, he passed the examination with a reasonable grade, and I actually improved my own understanding through teaching him. That experience showed me that helping others is rarely one-directional. I gave him time and explanations, but I received a much deeper understanding of the subject in return. Since then I have volunteered to help other classmates, partly because I enjoy it and partly because I know it strengthens my own knowledge. We stayed in touch after graduation and he sometimes reminds me about those study sessions. It is a small thing, but knowing that a few hours of my time made a real difference to someone else is genuinely satisfying.'],
  ['Describe a time you explored a forest.',
    'Kể về một lần bạn vào rừng chơi', 3,
    'I would like to describe a day I spent walking in a forest during a trip to a national park. My friends and I set out early in the morning with a local guide, because the paths were not clearly marked. The forest was much denser than I expected, and the air felt cool and damp even in the middle of the day. Our guide pointed out several plants used in traditional medicine, which I would never have noticed by myself. We also heard many birds but saw very few, since they stayed high in the trees. The walk took about five hours and was physically tiring, especially on the steep sections. What impressed me most was how quiet it was compared with the city. There was no traffic noise at all, only water, wind, and birds. That day reminded me how rarely I experience genuine silence, and it made me want to visit natural places more often. I bought a proper pair of walking shoes shortly afterwards, because my ordinary trainers were completely unsuitable on the wet ground. Since then I have joined two similar walks, and I now understand why people describe hiking as a form of rest rather than exercise.'],
  ['Talk about a time you participated in an activity for children.',
    'Kể về một lần tham gia hoạt động cho trẻ em', 3,
    'I would like to talk about a volunteer activity I joined at a primary school last summer. Our group organised a reading afternoon for about thirty children aged six to ten. My task was to read short stories aloud and then help the children draw pictures about what they had heard. At first it was harder than I expected, because young children lose concentration quickly and several of them wanted to talk at the same time. I learned to speak more slowly, use simpler words, and ask questions to keep them involved. By the end of the afternoon the room was full of drawings, and the children were clearly proud of their work. I went home tired but genuinely happy. That experience gave me much more respect for teachers, who do this every day. It also showed me that working with children requires patience and energy rather than knowledge, which was not what I had assumed beforehand. At the end of the afternoon one boy gave me his drawing to keep, which I still have somewhere. Small moments like that explain why volunteers keep returning even though the work is tiring and completely unpaid.'],
  ['Tell about a time you saved money to do something.',
    'Kể về một lần bạn tiết kiệm tiền để làm gì đó', 4,
    'I would like to talk about how I saved money to buy my first laptop. I was still a student with only a small part-time income, so I decided to save for about eight months. Every month I put aside a fixed amount as soon as I was paid, before spending on anything else. To reach the target faster, I reduced how often I ate out and stopped buying coffee on my way to class, which alone saved a surprising amount. There were moments when I was tempted to give up, especially when friends invited me on a trip that I had to refuse. When I finally bought the laptop, it felt much more valuable than if my parents had simply given it to me. More importantly, saving taught me a habit I still keep today. I now save a percentage of my income every month automatically, so I am prepared when something unexpected happens. I still have that laptop and it works perfectly well, partly because I look after it carefully. I suspect I would have been far less careful with something that had simply been given to me.'],
  ['Talk about a time you visited a tall building.',
    'Kể về một lần đi thăm tòa nhà cao tầng', 3,
    'I would like to talk about visiting the tallest building in my city with two friends. We went up to the observation deck on the top floor in the late afternoon, deliberately timing it so that we could see both daylight and the city lights. The lift itself was an experience, because it reached the top in less than a minute and my ears felt strange. From up there, the streets looked surprisingly small and quiet, even though I knew the traffic below was noisy. We stayed for about an hour, taking photographs and trying to identify familiar places. What struck me most was how differently the city looked from above: the parks appeared much larger and the buildings much more crowded than I had imagined. The ticket was fairly expensive, so it is not something I would do often. But as an occasional experience, I thought it was worth the money. Afterwards we walked back through the streets we had just been looking down on, which felt strange. Seeing a familiar place from an unfamiliar angle makes you notice things you have walked past hundreds of times without registering.'],
  ['Describe a time when you laughed out loud with a friend.',
    'Kể về một lần bạn cười lớn với người bạn', 3,
    'I would like to describe an evening when I could not stop laughing with my closest friend. We had decided to cook dinner together at her apartment to save money, and both of us were confident because we had watched a cooking video that morning. Neither of us actually followed the recipe properly. We guessed the quantities, ignored the cooking times, and added ingredients in the wrong order. The result was a dish that looked nothing like the photograph and tasted extremely strange, somehow both salty and sweet at the same time. Instead of being disappointed, we started laughing at how confident we had been beforehand. Then she tried to take a photograph of the food as evidence to send to her sister, and knocked over a glass of water across the table, which made everything worse and much funnier. We gave up completely, ordered noodles, and spent the rest of the evening laughing about it. It was not a special occasion, and nothing remarkable happened, but I remember that evening more clearly than many planned celebrations. I think that is what real friendship is like: the best memories often come from small failures rather than perfect moments.'],
  ['Describe a time when you faced a difficult question.',
    'Kể về một lần bạn gặp câu hỏi khó', 5,
    'I would like to describe a difficult question I was asked by my younger cousin, who is eight years old. He asked me why people have to work if working makes them tired and unhappy. It sounds simple, but I found it genuinely hard to answer honestly without being either depressing or dishonest. I could not simply say "for money", because he would ask why money matters. I thought for a moment and then explained that work is how people contribute something useful to others, and that being paid allows us to buy what other people have made. I also admitted that many people do not enjoy their jobs, and that choosing work you find meaningful is worth the effort. He seemed satisfied, but the question stayed with me for days. It made me examine my own reasons for the career I am pursuing, which I had never really questioned before. I have thought several times since about how children ask the questions adults have quietly agreed to stop asking. It is uncomfortable, but I think being asked something so simple occasionally is genuinely useful.'],
  ['Describe a time when you had a holiday or vacation.',
    'Kể về một lần bạn có 1 kỳ nghỉ lễ', 4,
    'I would like to describe a holiday I spent at the beach with my family during the Lunar New Year. We travelled about three hundred kilometres by car and stayed in a small guesthouse for four days. Our schedule was deliberately relaxed: we swam in the morning, ate seafood at local restaurants, and spent the afternoons resting or walking along the shore. One evening we watched fishermen bringing in their boats, which I found more interesting than any organised tourist activity. What made this holiday valuable was that all of us were free at the same time, which rarely happens because everyone is busy with work or study. We talked far more than we normally do at home, where everyone is occupied with their own things. Since then, I have started to believe that the destination matters much less than who you are with and how much time you actually have together. We are already discussing where to go next year, although finding a week when everyone is free will be the hard part. That is exactly why I value the trips we do manage to arrange.'],
  ['Describe a time when you worked in a team.',
    'Kể về một lần bạn làm việc nhóm', 5,
    'I would like to describe a group project I worked on during my final year at university. There were five of us, and we had to research a topic and present it to the whole class. At the beginning it did not go well, because everyone had different ideas and nobody wanted to take responsibility for the overall plan. After a week of very little progress, I suggested that we divide the work clearly and set a short meeting every Friday to check on each other. That simple change made a big difference. We finished on time and received one of the highest marks in the class. What I learned was that the difficulty in teamwork is rarely the work itself. The real challenge is communication and agreeing who does what. Since then, whenever I join a group, I try to clarify roles and deadlines in the very first meeting rather than assuming everyone understands the same thing. Two of the group are still close friends of mine, which I did not expect from a project that started so badly. Working through a difficult situation with people tends to create a stronger bond than simply getting along easily.'],
  ['Talk about a time you encountered bad weather.',
    'Kể về một lần gặp thời tiết xấu', 4,
    'I would like to talk about a day when I was caught in an unexpected storm. I had planned to visit a friend in another district, and the morning was bright and sunny, so I took my motorbike without a raincoat. About halfway there, the sky turned dark within minutes and extremely heavy rain started. The water on the road rose quickly and I could barely see ahead of me. I stopped under the roof of a small shop and waited for almost an hour, completely soaked. The shop owner kindly gave me hot tea while I waited, which I still remember. Eventually the rain eased and I continued, arriving very late. It was uncomfortable at the time, but the experience taught me a practical lesson: in my country the weather changes very quickly, so I now always keep a thin raincoat under my seat, no matter how clear the sky looks. I also stayed in touch with that shop owner and stop by occasionally when I pass through the area. A small kindness during an inconvenient hour is the part of that day I actually remember.'],
  ['Describe a time when you did an extreme sport.',
    'Kể về một lần bạn chơi thể thao mạo hiểm', 4,
    'I would like to describe the first time I tried rock climbing, at an indoor centre with two friends. I had always thought of myself as someone who avoided risk, so I was quite nervous. Before starting, an instructor explained the equipment and safety rules, which helped me feel more confident. My first attempt was not successful: I reached about halfway and then froze because I could not find the next handhold. I came back down feeling embarrassed. On the second attempt, however, I planned my route before starting and reached the top. The feeling when I got there was genuinely exciting, partly because I had failed the first time. I would not call myself an adventurous person even now, but that day changed how I think about fear. Being nervous does not mean you should not try; it usually means the attempt will feel more rewarding. Since that day I have returned to the climbing centre several times, and I have also tried a short outdoor route with a guide. I still would not describe myself as an adventurous person, but I have learned that the fear before starting is usually much larger than the actual difficulty.'],
  ['Talk about a time you met a new friend.',
    'Kể về một lần gặp một người bạn mới', 4,
    'I would like to talk about how I met one of my closest friends. It happened at an English conversation club that I joined about two years ago, mainly to practise speaking. On my first evening I felt awkward because I knew nobody, and I nearly left early. Then a girl sitting next to me started a conversation by asking a very simple question about where I lived. We discovered that we worked in similar fields and had both joined the club for the same reason. After that we began practising together every week, and gradually the friendship extended beyond English. Looking back, what strikes me is how easily I could have missed it by leaving early. That experience taught me that friendships often begin from very ordinary conversations, and that being willing to reply openly matters more than having something interesting to say. We now meet almost every week, sometimes to practise English and sometimes simply to have coffee and talk about work. She has also introduced me to several other people in the club, so my circle of friends has grown considerably. I am genuinely grateful that I decided to stay that evening.'],
  ['Describe a time when you received good news.',
    'Kể về một lần bạn nhận được một tin tốt', 4,
    'I would like to describe the day I received my examination results, which I had been waiting for nearly a month. I remember checking my email every morning and gradually losing hope. Then one afternoon, while I was at work, the notification finally arrived. I did not open it immediately because I was nervous, so I waited until I could step outside. When I saw that I had passed with a better score than I expected, I called my mother straight away. She was even happier than I was, which made the moment more memorable. That evening my family had a small celebration at home. What I remember most is not the score itself but the relief after months of studying. It also reminded me that good news feels much more meaningful when it comes after real effort rather than easily. I also learned something practical from that month of waiting. Constantly checking for results did not make them arrive faster; it only made me anxious. Now, when I am waiting for something important, I try to keep myself busy with other work instead of refreshing my email every hour.'],
  ['Describe a time when you made a great effort.',
    'Kể về một lần bạn nỗ lực', 4,
    'I would like to describe the period when I was preparing for an important English examination while working full time. For about six months I studied every evening from nine to eleven, and also several hours at weekends. It was genuinely difficult because I was often tired after work, and there were weeks when I felt that I was not improving at all. What kept me going was breaking the goal into very small daily tasks: twenty new words, one listening exercise, and one recorded speaking answer. On days when I felt exhausted, I allowed myself to do only the minimum rather than skipping entirely. In the end I reached the level I needed. Looking back, the effort mattered more than the certificate, because it proved to me that consistency over months beats intense effort for a few days. I now apply the same approach to other goals. What also helped was telling a few friends about my goal, because it made it harder to quietly give up. On the days I wanted to stop, I reminded myself that I only needed to finish that single day, not the whole six months. That way of thinking is probably the most useful thing I gained.'],
  ['A time you asked a good question.',
    'Kể về lần bạn đặt một câu hỏi hay', 3,
    'I would like to talk about a question I asked during a training session at work. The trainer was explaining a new process, and everyone was nodding as if they understood. I did not fully understand one step, and although I hesitated because I did not want to look slow, I decided to ask him to explain it again with a concrete example. To my surprise, several colleagues immediately said they had the same confusion. The trainer then realised his explanation had been unclear and spent another ten minutes on it. Afterwards two people thanked me for asking. That experience changed my attitude towards asking questions. I used to think that asking meant admitting weakness, but I now believe a good question often helps the whole group, and staying silent to protect your image usually costs everyone more time later. Since then I have made it a habit to ask at least one question in every meeting or training session I attend. Sometimes the answer is obvious and I feel slightly foolish, but far more often other people are grateful because they had the same doubt and did not want to speak first.'],
  ["Talk about a time you did something you didn't want to do.",
    'Kể về một lần bạn làm việc mình không muốn làm', 3,
    'I would like to talk about a time I had to attend a family gathering when I really wanted to stay at home and rest. It was a weekend after a very busy week, and my mother asked me to come because a relative had travelled a long way to visit. I agreed reluctantly and, honestly, I was in a bad mood on the way there. However, once I arrived, the atmosphere was warm and I ended up enjoying the afternoon. I heard family stories I had never known, and my grandmother seemed genuinely happy that everyone came. On the way home I realised I would have regretted staying at home. That day taught me that I am not always the best judge of what I need. Sometimes the thing I want to avoid is exactly the thing that improves my mood. Since then I have tried to notice the difference between genuinely needing rest and simply feeling lazy. When someone asks me to join something and my only reason for refusing is tiredness, I usually go anyway. More often than not, I come home in a better mood than when I left.'],
  ['Describe a time when you worked with both elderly people and children.',
    'Kể về một lần bạn làm việc với người già và trẻ', 3,
    'I would like to describe a community activity I joined where we organised an afternoon connecting elderly residents with young children. My task was to help the two groups do simple craft work together. It was more difficult than I expected, because the children were noisy and impatient while several elderly people could not hear well. At first the room felt chaotic. What worked was pairing one child with one older person and giving each pair a single clear task. After that the atmosphere changed completely. The children became calmer, and many elderly people started telling stories about their own childhood. By the end, both groups clearly did not want to leave. That day showed me that people of very different ages can connect easily, but they usually need a simple shared activity rather than just being placed in the same room. I joined the same activity twice more after that. Each time I noticed that the elderly participants prepared something to show the children, and the children clearly looked forward to it. It made me think that these two groups are often kept apart unnecessarily, when both of them benefit from spending time together.'],
  ['Talk about a time you watched a sports match.',
    'Kể về một lần xem một trận đấu thể thao', 3,
    'I would like to talk about watching an important football match with my friends at a coffee shop. It was a national team game, so the place was completely full and we had to arrive an hour early to get seats. The atmosphere was remarkable: every time our team attacked, the whole shop shouted together, and strangers were talking to each other as if they were friends. Our team scored in the last few minutes and won, and afterwards people went out into the street celebrating. I am not a serious football fan and I rarely watch matches alone, but that evening I understood why people love it. The football itself mattered less than the feeling of thousands of people caring about the same thing at the same moment. It is one of the few experiences that connects an entire country like that. Since that night I have watched several matches with the same group of friends. I still do not follow the league closely and I cannot name most of the players, but I now understand that for many people football is less about the sport and more about belonging to something bigger than themselves.'],
  ['Talk about a time you attended a music festival.',
    'Kể về một lần tham gia lễ hội âm nhạc', 3,
    'I would like to talk about a music festival I attended in a park near my city last summer. I went with three friends, and we arrived in the late afternoon to find a good spot. There were several stages, so we moved between them depending on which band we wanted to hear. The best moment was in the evening when the main band performed and the whole crowd sang together. There were some problems: the queues for food were extremely long and the ground became muddy after a short rain. Even so, I enjoyed it far more than listening to the same music at home. Live performance has an energy that recordings cannot reproduce. I would go again, although next time I would bring proper shoes and eat before arriving rather than relying on the food stalls. Looking back, what I remember most clearly is not any particular song but the atmosphere: thousands of people singing the same words at the same time under an open sky. It is the kind of experience that makes an ordinary summer weekend feel genuinely memorable, which is why I would go again.'],
  ['Talk about a time you visited a new city.',
    'Kể về một lần thăm một thành phố mới', 4,
    'I would like to talk about the first time I visited Da Nang, which I had heard about for years but never seen. I travelled there with two friends for a long weekend. We deliberately avoided planning too much, so we spent the first day simply walking around the city and along the beach. What surprised me most was how clean and organised it felt compared with larger cities, and how easy it was to move around. We tried local seafood at a small market restaurant, which was far better and cheaper than the tourist places. On the second day we rented motorbikes and rode along the coast, which was the highlight of the trip. Visiting a new city always makes me realise how much my daily routine limits what I notice. Everything there felt interesting simply because it was unfamiliar. We stayed only three days, which was not enough, and I already have a list of places I want to see next time. The trip also changed how I think about my own city. When I came home, I deliberately spent a weekend walking around neighbourhoods I had never explored, and found several places I liked.'],
  // Khác đề "wanted something but couldn't get it": đề này nói riêng về việc
  // MUA, nên giữ cả hai.
  ["Describe a time when you wanted to buy something but couldn't.",
    'Kể về một lần bạn muốn mua gì đó nhưng không thể', 3,
    'I would like to describe a time when I wanted to buy a camera but could not. It was about a year ago, when I had become interested in photography and had been researching models for several weeks. I found one that suited me perfectly: good image quality, not too heavy, and with lenses I could add later. The problem was the price, which was roughly three months of my savings at that time. I visited the shop twice and even held it in my hands, but each time I decided to wait. What made it harder was that a friend bought the same model shortly afterwards and kept showing me his photographs. Looking back, I think the decision was correct. I needed that money for a course which turned out to be far more useful for my career. I did eventually buy a cheaper second-hand camera six months later, and honestly it has been enough for everything I actually do. What I took from that experience is that waiting is not the same as giving up. If I still want something after a few months, it is probably a genuine need rather than an impulse, and by then I can usually afford it without sacrificing anything important.'],
  ["Talk about a time you wanted to buy something but couldn't.",
    'Kể về một lần muốn mua gì đó nhưng không được', 3,
    'I would like to talk about a pair of running shoes I wanted last year but could not buy. I had started running regularly and my old shoes were clearly worn out, so I went to a sports shop during a sale. I found exactly the model I wanted at a good discount, but when I asked for my size, the assistant checked and told me they had sold out that morning. I tried two other branches in the city and neither had it either. I was quite frustrated because the sale ended that weekend. In the end I bought a different brand at full price, which was more expensive and, at first, less comfortable. After a few weeks, though, they broke in and I now prefer them to the ones I originally wanted. It taught me that not getting exactly what you planned is often less important than it feels at the time. I have also become more relaxed about sales since then. Discounts create a feeling of urgency that makes you decide badly, and the thing you buy in a rush is often not the thing you actually needed in the first place.'],
  ['Talk about a time you visited an old building.',
    'Kể về một lần thăm một tòa nhà cổ', 3,
    'I would like to talk about a visit to an old temple in the centre of my city, which I went to with my parents last year. The building is more than two hundred years old and is surrounded by very tall trees, so the moment you walk through the gate the noise of the traffic disappears. What struck me most was the woodwork: the pillars and roof beams were carved by hand, and a guide explained that the same techniques are almost never used now. My mother told me she had visited the same place as a child, and very little had changed. We stayed for about an hour, walking slowly and reading the information boards. I had passed that building hundreds of times on my motorbike without ever going inside, which I found slightly embarrassing. Since then I have deliberately visited two other historic sites in my own city. It is strange how we travel far to see old buildings while ignoring the ones on our doorstep. It is strange how we travel far to see old buildings while ignoring the ones on our doorstep. Since that visit I have also started reading a little about the history of my own district, which I had never bothered to do before.'],
  ['Talk about a time you received a gift.',
    'Kể về một lần bạn được tặng quà', 5,
    'I would like to talk about a gift I received from my parents when I finished secondary school. It was a wristwatch, not an expensive one, but they had clearly chosen it carefully because they knew I disliked anything flashy. I remember being surprised, because we were not a family that gave presents often, and my father was not the kind of person to plan something like that. What made it meaningful was the note inside the box, which simply said they were proud of me. I still wear that watch almost every day, and it has been repaired twice rather than replaced. Friends sometimes ask why I do not buy a newer one, and I find it difficult to explain briefly. The value of a gift usually has very little to do with its price. What matters is the evidence that someone thought about you specifically, and that is why I have kept it for so long. Looking back, that watch also changed how I choose presents for other people. I now spend far less money than I used to, but far more time thinking about what the person actually likes.'],
  ['Talk about a time you attended an English course.',
    'Kể về một lần bạn tham gia một khóa học tiếng Anh', 4,
    'I would like to talk about an English speaking course I attended about a year ago. I signed up because although my reading was reasonable, I could barely hold a conversation without long pauses. The class had eight students and met twice a week in the evening. At first I hated it, honestly, because we were made to speak from the very first lesson and I felt embarrassed about my mistakes. The teacher had a useful rule: nobody was allowed to apologise for their English. After a few weeks the atmosphere became much more relaxed and I stopped translating every sentence in my head before speaking. By the end of the three months I could talk for two or three minutes without freezing. The course did not make me fluent, but it removed most of the fear, which was the real obstacle. I would recommend a small class over an app for exactly that reason. An application can correct your grammar, but it cannot put you in a room where you have to keep talking even when you are unsure, and that is what I needed most.'],
  ['Talk about a challenge you have faced.',
    'Kể về một thử thách của bạn', 4,
    'I would like to talk about the challenge of moving to a new city alone for work. I had lived with my family my whole life, so suddenly I had to manage rent, cooking, and every small problem by myself. The first month was genuinely difficult. I knew nobody, my apartment felt empty in the evenings, and I made several expensive mistakes, including signing a rental contract without reading it properly. What helped was building a routine: I joined a badminton group at weekends and found a coffee shop where I worked on Sunday mornings. Gradually the city stopped feeling foreign. Looking back, the hardest part was not the practical tasks but the loneliness, which nobody had warned me about. I would still make the same decision, because that year taught me more about myself than the previous five. I now understand that being uncomfortable for a while is often the price of growing. I now understand that being uncomfortable for a while is often the price of growing. Whenever something feels intimidating now, I remind myself how quickly that first difficult month became normal.'],
  ['Tell me a time you read a good book.',
    'Kể về một lần bạn đọc 1 cuốn sách hay', 4,
    'I would like to talk about a novel I read last winter, which a colleague recommended after I mentioned that I had stopped reading. It was about three generations of one family and how their lives changed through a difficult period of history. I remember starting it without much expectation and then finishing almost four hundred pages within a week, which had not happened for years. What made it good was that the characters behaved inconsistently, the way real people do, rather than following a neat plan. There was one chapter about a mother deciding whether to send her son away that I read twice. After finishing it I lent the book to my sister, and we spent an evening arguing about whether the ending was hopeful or sad. That conversation was almost as enjoyable as the book itself. It reminded me that reading is not only a private activity, and I have kept the habit since then. It reminded me that reading is not only a private activity, and I have kept the habit since then. I now finish roughly one novel a month, and I always try to talk to somebody about it afterwards.'],
  ['Talk about a place you have traveled to.',
    'Kể về nơi bạn đã từng đi du lịch', 4,
    'I would like to talk about Hoi An, a small town in central Vietnam that I visited two years ago. What makes it unusual is that the old quarter has been preserved almost completely, so walking through it in the evening, with lanterns along the river, feels like being in a different century. We stayed three nights in a family guesthouse rather than a hotel, which turned out to be the best decision because the owner cooked breakfast and told us where local people actually ate. During the day it was extremely hot and crowded with tourists, so we adjusted our schedule: out early, resting in the afternoon, then out again after five. The tailoring shops are famous there and I had a shirt made, which I still wear. I have travelled to several places since, but Hoi An is the one I recommend most often, mainly because it rewards walking slowly rather than sightseeing quickly. Hoi An rewards walking slowly rather than sightseeing quickly, and that is the main thing I took away from the trip. I have applied the same approach to every holiday since, choosing fewer places and staying longer in each one.'],
  ['Talk about a time you broke a rule.',
    'Kể về một lần phạm luật', 3,
    'I would like to talk about a time I broke a rule at school, when I was about fifteen. Our school did not allow students to leave the grounds during lunch break, but a group of us decided to go to a noodle shop across the road because we were tired of the canteen food. We were caught almost immediately by a teacher who happened to be driving past. I remember standing in the office feeling far more embarrassed than frightened, because the reason was so trivial. We had to write an explanation and our parents were informed. Looking back, the rule existed for safety reasons that I did not think about at the time; the road outside was genuinely dangerous. What I learned was less about obedience and more about consequences: I had risked something real for a bowl of noodles. I have been reasonably careful about rules since then, although I do still question the ones that seem pointless. I have been reasonably careful about rules since then, although I do still question the ones that seem pointless. The difference now is that I ask first instead of simply ignoring them and hoping nobody notices.'],
  ['Talk about a time someone asked you to stop doing something.',
    'Kể về một lần ai đó yêu cầu dừng làm việc gì', 3,
    'I would like to talk about a time my flatmate asked me to stop playing music late at night. I had a habit of working until midnight with music on, and although I thought the volume was low, the walls in our building are very thin. One evening she knocked on my door and explained, politely but clearly, that she had been unable to sleep properly for two weeks. My first reaction was defensive, because nobody enjoys being told they are inconsiderate. But she was obviously right, and I had simply never considered it. I bought headphones the next day, which solved the problem completely. What I appreciated afterwards was that she spoke to me directly instead of complaining to other people or leaving a note. That experience made me more willing to raise small issues early myself, because two weeks of silent irritation is far worse than one slightly awkward conversation. Two weeks of silent irritation is far worse than one slightly awkward conversation, and I have repeated that to myself many times since. We shared that apartment for another year without a single serious argument.'],
  ['Talk about a time you got lost.',
    'Kể về một lần bị lạc đường', 4,
    'I would like to talk about getting lost during a trip to the mountains with two friends. We were walking a trail that was supposed to take three hours, but at some point we took a smaller path that looked like a shortcut. After about forty minutes we realised the markers had disappeared, and worse, my phone had no signal. It was late afternoon, so we were genuinely worried about losing the light. We decided to walk back rather than continue forward, which was frustrating but sensible, and after an hour we found the original trail again. We reached the village just before dark, exhausted and very quiet. Nothing serious happened, but it could have. Since then I always download an offline map before any walk, and I have learned to be suspicious of shortcuts that are not marked. Getting lost taught me more about preparation than any advice I had read beforehand. Getting lost taught me more about preparation than any advice I had read beforehand. I have also learned that turning back early, while it feels like failure, is usually the sensible decision rather than a weak one.'],
  ['Talk about a time you had to put in a lot of effort.',
    'Kể về một lần bạn phải dành nhiều nỗ lực', 4,
    'I would like to talk about the effort I put into learning to drive. It took me far longer than most people, partly because I was nervous in traffic and partly because I could only practise at weekends. I failed the test the first time, which was discouraging because I had convinced myself I was ready. My instructor told me something useful afterwards: the problem was not my driving but that I hesitated too long at junctions, which made me look uncertain. So for two months I practised only that, driving the same busy route again and again until it felt ordinary. I passed the second attempt comfortably. What I took from the experience is that effort works best when it is aimed at one specific weakness rather than spread across everything. Repeating what I was already good at had felt productive, but it was the uncomfortable practice that actually changed the result. Repeating what I was already good at had felt productive, but it was the uncomfortable practice that actually changed the result. I now apply the same idea to my English, spending most of my time on the skills I am worst at.'],
  ['Talk about your favorite outfit.',
    'Kể về trang phục yêu thích của bạn', 3,
    'I would like to talk about my favourite outfit, which is very simple: a plain white shirt, dark jeans, and brown leather shoes. I bought the shirt about three years ago and I have replaced it twice with the same model, which probably says something about me. I like it because it works almost everywhere. I can wear it to the office, to dinner with friends, or to a family event just by changing the shoes. I am not particularly interested in fashion, and I find choosing clothes every morning genuinely tiring, so having a combination I trust removes one decision from the day. My sister teases me for looking the same in every photograph. She is right, but I would rather look slightly boring and comfortable than spend twenty minutes deciding. The only thing I am careful about is fit, because even cheap clothes look reasonable if they fit properly. The only thing I am careful about is fit, because even inexpensive clothes look reasonable if they fit properly. A tailor near my house charges very little to adjust sleeves, and it makes a surprising difference.'],
  ['Tell me a time you went to see a work of art.',
    'Kể về một lần bạn đi xem một tác phẩm nghệ thuật', 3,
    'I would like to talk about visiting a small exhibition of lacquer paintings in my city about six months ago. A friend who studies design invited me, and honestly I agreed mainly to be polite, because I know very little about art. The gallery was quiet, with perhaps twenty paintings, all by one Vietnamese artist. What surprised me was how much the surface changed depending on where you stood: the lacquer reflected light so the colours shifted as you moved. My friend explained roughly how the technique works, which involves many layers and a great deal of patience. There was one painting of a village at dusk that I stood in front of for several minutes without really knowing why. I did not become an art enthusiast after that afternoon, but I did understand something I had missed before: looking at a painting properly takes time, and rushing through a gallery is the same as not going. Looking at a painting properly takes time, and rushing through a gallery is the same as not going. I have visited two more exhibitions since, and each time I deliberately choose a few works rather than trying to see everything.'],
  ['Talk about a time someone was rude to you.',
    'Kể về một lần ai đó thiếu lịch sự với bạn', 3,
    'I would like to talk about an incident at a shop about a year ago. I was returning a pair of headphones that had stopped working after two weeks, and I had the receipt with me. The assistant was clearly irritated from the beginning, spoke to me sharply, and suggested that I must have damaged them myself. I felt embarrassed because other customers were listening. My first instinct was to argue back, but I decided instead to ask calmly to speak to the manager. The manager apologised and replaced the headphones without any difficulty. Afterwards I thought about it quite a lot. It is possible the assistant was having a terrible day, and I have no idea what had happened before I arrived. That does not excuse it, but it did stop me complaining about her by name. What I took from it is that staying calm was more effective than matching her tone. What I took from it is that staying calm was more effective than matching her tone. I also try to remember that when I am tired and short with somebody, they have no idea what my day has been like either.'],
  ['Talk about a time you were in a hurry.',
    'Kể về một lần bạn vội vàng', 3,
    'I would like to talk about a morning when I was extremely rushed because of an important meeting. I had prepared everything the night before, but my motorbike would not start, which I discovered fifteen minutes before I needed to leave. I tried for a few minutes, then gave up and ordered a taxi, which took another ten minutes to arrive because of the rain. I spent the whole journey checking the time and rehearsing an apology. In the end I arrived four minutes late, which nobody even mentioned. Looking back, the interesting part is how much stress I created over something that turned out not to matter. I had imagined a disaster that did not happen. Since then I try to leave earlier for anything important, but I also try to remind myself that being slightly late is rarely the catastrophe it feels like in the moment. Since then I try to leave earlier for anything important, but I also try to remind myself that being slightly late is rarely the catastrophe it feels like in the moment. I have also had my motorbike serviced regularly, which was the actual lesson.'],
  ['Talk about your sleeping habits.',
    'Kể về thói quen ngủ của bạn', 3,
    'I would like to talk about my sleeping habits, which have changed considerably over the past two years. When I was a student I often stayed awake until one or two in the morning, then struggled through the following day feeling exhausted. After I started working, that pattern became impossible, so I gradually built a better routine. Now I try to go to bed around eleven and get up at half past six, even at weekends, because keeping the same schedule makes waking up much easier. The biggest change was stopping using my phone in bed, which used to keep me awake for an extra hour without me noticing. I also avoid coffee after the early afternoon. I still sleep badly when I am worried about something, but overall I feel far more alert during the day than I used to. The clearest benefit is at work. When I sleep properly I make far fewer careless mistakes and I need much less coffee to concentrate in the afternoon. I would tell anyone struggling with sleep to start with a fixed wake-up time rather than a fixed bedtime, because that is what actually reset my rhythm.'],
  ['Describe a time when you went to an amusement park.',
    'Kể về một lần bạn đi công viên giải trí', 3,
    'I would like to talk about a visit to an amusement park with my cousins about three years ago. It was during the summer holiday and the park was extremely crowded, so we spent almost as much time queuing as we did on the rides. My youngest cousin was too short for most of the big attractions, which upset her at first, so we took turns staying with her on the smaller ones. The highlight for me was a roller coaster that I had been nervous about all morning. I remember gripping the bar and deciding not to look down, and then laughing for about a minute afterwards out of pure relief. We ate far too much fried food and got sunburnt because none of us had brought a hat. By the evening we were exhausted and completely satisfied. Looking back, the queues that annoyed me at the time are where most of our conversations happened, so they were not really wasted. I would go again, but I would arrive much earlier in the morning and bring sun cream. I would go again, but I would arrive much earlier in the morning and bring sun cream. Looking back, the day is also a reminder that the best trips are usually the ones where nothing goes exactly to plan.'],
  ['Talk about a time you were helped.',
    'Kể về một lần bạn được giúp đỡ', 5,
    'I would like to talk about a time a stranger helped me when my motorbike broke down on the way to work. It stopped completely on a busy road, during the morning rush, and I had no idea what was wrong. I pushed it onto the pavement and stood there feeling rather helpless. After a few minutes a man who ran a small repair shop nearby walked over, looked at the engine, and told me the spark plug was dirty. He cleaned it, refused to take any money, and simply said he had been in the same situation before. I arrived at work only twenty minutes late. What struck me was that he had no reason to help, and I had not even asked him. I have thought about that morning many times since, usually when I see somebody standing beside a broken vehicle. I now stop and ask if they need anything, which I would probably not have done before. Being helped by a stranger changes how willing you are to help other people. Being helped by a stranger changes how willing you are to help other people. I also learned a little about basic maintenance that morning, and I now check the spark plug myself every few months instead of waiting for a breakdown.'],
  ['Tell me about a time when you met a foreigner.',
    'Kể về một lần bạn gặp một người nước ngoài', 3,
    'I would like to talk about meeting a foreign tourist in my city about two years ago. I was sitting in a coffee shop when a man at the next table asked me, in very slow English, how to get to the railway station. His map was clearly out of date, so I explained the route and then decided to walk with him for part of the way. He was from Germany and had been travelling in Vietnam for three weeks. We talked about food mostly, because he was fascinated by street breakfast and could not understand why we ate soup in the morning. I remember being nervous about my English at first, but after a few minutes I stopped worrying about mistakes because he clearly understood me. Before we parted he gave me a small chocolate bar from his bag, which felt like an odd but genuine gesture. That conversation lasted perhaps twenty minutes, and it did more for my confidence in speaking English than several weeks of studying grammar had done. That conversation did more for my confidence than several weeks of grammar study. Since then I have deliberately spoken to tourists when they look lost, partly to help them and partly because it is free speaking practice.'],
  ['Tell me about a time when you changed your daily routine.',
    'Kể về một lần bạn thay đổi thói quen hằng ngày', 5,
    'I would like to talk about the time I changed my routine to start exercising in the morning. Previously I went to the gym after work, but I was usually too tired and ended up skipping it two or three times a week. So I decided to move it to six in the morning instead, which meant going to bed considerably earlier. The first two weeks were genuinely unpleasant. Waking up in the dark felt unnatural and I nearly gave up several times. What helped was preparing my clothes the night before, so that in the morning there was no decision to make. After about a month it became normal, and I noticed I was much more alert during the working day. The unexpected benefit was that my evenings became free, so I now read or cook instead of feeling guilty about the gym. I would say the hardest part of changing a routine is not the new habit itself but the first fortnight, when nothing feels natural yet. The hardest part of changing a routine is not the new habit itself but the first fortnight, when nothing feels natural yet. I have used the same approach twice since, and knowing that the discomfort is temporary makes it much easier.'],
  ['Talk about a time you shared something with someone.',
    'Kể về một lần bạn chia sẻ thứ gì đó với người khác', 4,
    'I would like to talk about a time I shared my lecture notes with a classmate at university. He had missed almost two weeks of classes because his father was ill, and he was clearly worried about falling behind before the examinations. I offered him my notes, and instead of simply sending photographs I suggested we go through them together in the library. We ended up meeting three times, and explaining the material to him forced me to understand it much better myself. He passed the exam comfortably, which was a relief for both of us. What I did not expect was how much I gained from it: teaching something is a far more effective way of revising than reading alone. We remained friends afterwards and he helped me with a statistics course the following semester. Looking back, I think sharing something you have worked hard for feels risky at first, but in my experience it almost always comes back to you in some form. Sharing something you have worked hard for feels risky at first, but in my experience it almost always comes back to you in some form. That is probably the main reason I now volunteer to explain things in team meetings.'],
  ['Talk about a time you (or someone you know) changed jobs.',
    'Kể về một lần bạn hoặc người bạn quen thay đổi công việc', 4,
    'I would like to talk about my cousin, who changed her job about a year ago. She had worked in a bank for six years and was reasonably well paid, but she came home exhausted every evening and rarely talked about her work with any enthusiasm. Eventually she decided to move into training and development at a smaller company, even though it meant a slightly lower salary. Everybody in the family advised her against it, including me, because the bank felt safe. The first few months were difficult: she had to learn a great deal quickly and she doubted her decision more than once. But when I met her at a family dinner recently, she was noticeably different, talking about her projects without being asked. That experience changed my own thinking about work. I used to assume stability was the most important factor, and I now believe that spending years in a job you dislike has a real cost, even if it does not appear on a payslip. Watching her go through it also made me more honest about my own situation. I have since started learning skills outside my current role, so that if I ever want to move, the decision will be a choice rather than a leap.'],
  ['Tell me about a time when you had to wait for something important.',
    'Kể về một lần bạn phải chờ đợi điều gì quan trọng', 3,
    'I would like to talk about waiting for the results of an important examination. I had taken the test in June and the results were not published until the end of July, so there were nearly six weeks of uncertainty. At first I tried to forget about it, but that was impossible because everybody kept asking. I checked the website far more often than was reasonable, sometimes several times a day, even though I knew the date. The waiting was harder than the examination itself, mainly because there was nothing I could do to change the outcome. What eventually helped was starting a small project at home, repainting my room, which gave me something physical to concentrate on. When the results finally appeared they were better than I had expected. Looking back, I learned that anxiety while waiting is almost entirely wasted energy. Now, when I am waiting for something out of my control, I deliberately fill the time rather than watching for news. Now, when I am waiting for something out of my control, I deliberately fill the time rather than watching for news. It does not remove the anxiety completely, but it stops six weeks of waiting from feeling like six weeks of worrying.'],
  ['Tell me about a time when someone gave you a compliment.',
    'Kể về một lần ai đó khen ngợi bạn', 3,
    'I would like to talk about a compliment I received from a manager at work last year. I had prepared a presentation for a client meeting, and I was quite nervous because it was the first time I had presented alone. Afterwards, she said in front of the whole team that my explanation had been clearer than anything she had heard from our department that month. I remember feeling embarrassed and not knowing how to reply, so I probably just said thank you and looked at the floor. But I thought about it for days afterwards. What made it valuable was that it was specific: she did not say "good job", she said exactly what had worked and why. That made it useful as well as pleasant. Since then I have tried to give compliments the same way, mentioning the particular thing somebody did rather than something general. A vague compliment is forgotten immediately, whereas a specific one can change how somebody sees their own ability. A vague compliment is forgotten immediately, whereas a specific one can change how somebody sees their own ability. I have also become better at accepting praise instead of dismissing it, which I used to do automatically.'],
  ['Tell me about a sports event you watched or took part in.',
    'Kể về một sự kiện thể thao bạn xem hoặc tham gia', 4,
    'I would like to talk about a football match I watched with friends at a small café near my house. It was an important national game, so the place was completely full and people were standing in the doorway. I am not a particularly keen football fan, and I could not name most of the players, but the atmosphere was impossible to ignore. Every time our team came close to scoring, the whole café shouted at once, and when we finally scored in the second half a man behind me spilled his drink over my shoulder without noticing. We won by one goal. Afterwards people drove around the streets waving flags for about an hour. What I found interesting was not the football itself but how completely strangers behaved like friends for two hours. That night made me understand why people follow sport so seriously: the game is really just an excuse for a few thousand people to feel the same thing at the same moment. The game is really just an excuse for a few thousand people to feel the same thing at the same moment. I have watched several matches with the same group since, and I now understand the appeal far better than I did before.'],
  ['Tell me about a time when technology helped you.',
    'Kể về một lần công nghệ giúp ích cho bạn', 4,
    'I would like to talk about how a simple translation application helped me during a work trip abroad. I had to attend a two-day meeting in a country where I spoke none of the language, and although the meetings themselves were in English, everything outside them was not. On the first evening I could not read the menu in a restaurant, so I used my phone camera to translate it, which worked surprisingly well. The next day I used the same app to ask a taxi driver to wait for me, and to explain to a pharmacist that I needed something for a headache. None of the translations were perfect, and one of them clearly amused the pharmacist, but they were good enough. What struck me was how much that small piece of software reduced my anxiety about being alone in an unfamiliar place. It has not made me lazy about learning languages, but it has made me far more willing to travel somewhere I do not speak the language. It has not made me lazy about learning languages, but it has made me far more willing to travel somewhere I do not speak the language. On the flight home I even used it to read a newspaper, which was oddly satisfying.'],
  ['Tell me about something new you learned recently.',
    'Kể về điều gì mới mà bạn học được gần đây', 4,
    'I would like to talk about learning basic photography over the last few months. I bought a second-hand camera mainly because I was tired of my holiday photographs looking flat and lifeless. At first I used the automatic setting and the results were no better than my phone, which was discouraging. Then a friend explained the relationship between aperture, shutter speed, and light, and suggested I shoot only in manual mode for a month even if the pictures were bad. Many of them were bad. But gradually I began to understand why a photograph had failed, which is quite different from simply knowing that it had. I now take the camera out most weekends and walk around my neighbourhood looking for light rather than looking for subjects. What I enjoy most is not the photographs themselves but the fact that I notice things I used to walk past. Learning something technical changed the way I see an ordinary street. Learning something technical changed the way I see an ordinary street. I have also printed a few of the pictures, which I had not done for years, and my parents have put one of them in the living room.'],
  ['Tell me about a time when you had a different opinion from an older or younger person.',
    'Kể về một lần bạn có quan điểm khác với người lớn tuổi hoặc nhỏ tuổi hơn', 4,
    'I would like to talk about a disagreement I had with my father about my career. He believed I should stay in a stable government job, because that is what his generation valued most, whereas I wanted to move to a private company with more opportunity but far less security. We argued about it several times over about two months, and neither of us was really listening at first. What eventually changed the conversation was when I stopped defending my choice and asked him what specifically worried him. His answer was not about money at all; he was afraid I would be dismissed without any protection. Once I understood that, I could explain my plan properly, including what I would do if the job failed. He still disagreed, but he accepted it. Looking back, that experience taught me that a difference in opinion between generations is usually a difference in what each person is afraid of. Asking about the fear is far more productive than repeating your argument more loudly. Asking about the fear is far more productive than repeating your argument more loudly. I have used the same approach with my younger sister since, and it works in both directions, because her worries were also nothing like what I had assumed.'],
  ['Tell me about a time when you took part in a volunteer or community activity.',
    'Kể về một lần bạn tham gia hoạt động thiện nguyện hoặc cộng đồng', 4,
    'I would like to talk about a community clean-up I joined in my neighbourhood last year. A group of residents organised it because a canal near our street had become badly polluted, and about forty people turned up on a Sunday morning. We were given gloves and bags and spent nearly four hours collecting rubbish along the bank. It was hot, unpleasant work, and the amount of plastic we pulled out was genuinely shocking. What surprised me was how many people I met who lived only two streets away and whom I had never spoken to before. An elderly man brought tea for everyone at midday, which nobody had asked him to do. By the afternoon the difference was visible, and somebody took photographs to post in our neighbourhood group. The canal is dirty again now, which is discouraging, but I have joined two more clean-ups since. I have also become far more careful about my own rubbish, because I have seen where it ends up. I have also become far more careful about my own rubbish, because I have seen where it ends up. The other lasting result is that I now know perhaps fifteen neighbours by name, which makes the street feel like an actual community.'],
  ['Tell me about a time when you had a major responsibility.',
    'Kể về một lần bạn có trách nhiệm lớn', 4,
    'I would like to talk about a time I was left in charge of my department for two weeks while my manager was abroad. I had been working there less than a year, so I was surprised she chose me. The responsibility itself was mostly practical: approving small expenses, answering client emails, and making sure two deadlines were met. What I had not expected was the mental weight of it. I found myself checking my email late at night in case something had gone wrong. One genuine problem did arise, when a supplier failed to deliver on time, and I had to decide whether to wait or find an alternative. I chose the alternative, which cost slightly more, and my manager agreed with the decision when she returned. Those two weeks changed how I see leadership. The difficult part is not making decisions but accepting that you cannot be certain you have made the right one until much later. The difficult part is not making decisions but accepting that you cannot be certain you have made the right one until much later. Since then I have volunteered for that kind of cover twice, because the discomfort is where most of the learning happens.'],
  ['Talk about a presentation you gave to other people.',
    'Kể về một bài trình bày bạn từng thực hiện', 4,
    'I would like to talk about a presentation I gave at work about six months ago. I had to explain the results of a small project to around twenty colleagues, including two senior managers, and I was extremely nervous because I dislike speaking in front of groups. I prepared far too many slides at first, about thirty, and when I practised at home I realised it would take almost an hour. So I cut it down to twelve slides and decided to talk through the story rather than read the text. On the day my voice shook for the first minute or two, then I forgot about being nervous because somebody asked a question and I knew the answer. It lasted fifteen minutes and went far better than I had feared. What I learned was that preparation should be about cutting material rather than adding it. I also learned that the audience wants you to succeed, which is easy to forget when you are standing in front of them. I also learned that the audience wants you to succeed, which is easy to forget when you are standing in front of them. I now volunteer for presentations rather than avoiding them, and each one is noticeably less frightening than the last.'],
  ['Talk about a time when you tried something new.',
    'Kể về một lần bạn thử điều gì mới', 4,
    'I would like to talk about the first time I tried cooking a foreign dish, specifically Japanese ramen, at home. I had eaten it in restaurants many times and assumed it could not be too difficult. It was. The broth alone took nearly five hours, and I had to visit three shops to find the right noodles and a particular type of miso. My first attempt was disappointing: the broth was too salty and the egg was overcooked. My family ate it politely, which was somehow worse than complaining. I tried again two weeks later with less salt and more attention to timing, and the result was genuinely good. What I enjoyed most was not the dish but the process of understanding why each step existed. Since then I have cooked it perhaps six times, and I now improvise instead of following the recipe exactly. Trying something new usually means being bad at it first, and I think many people give up during that stage rather than after it. Trying something new usually means being bad at it first, and many people give up during that stage rather than after it. I try to remind myself of that whenever I start something and the early results are disappointing.'],
  ['Tell me about a time when you changed schools.',
    'Kể về một lần bạn chuyển trường', 3,
    'I would like to talk about changing schools when I was thirteen, because my family moved to a different district. I did not want to go. I had been at my old school for years and all my friends were there, so the first month was genuinely miserable. I ate lunch alone and pretended to be busy so it looked deliberate. What eventually helped was joining the school football team, not because I was good at it but because it forced me into a group where talking was unavoidable. Within about six weeks I had two friends, and by the end of the year I preferred the new school to the old one. Looking back, I think schools could do far more to help new students, because being introduced once to a class of forty people achieves almost nothing. A simple system of pairing a new student with somebody for the first two weeks would have made an enormous difference to me, and it would cost nothing. A simple system of pairing a new student with somebody for the first two weeks would have made an enormous difference to me, and it would cost nothing. I still remember which boy first spoke to me, which shows how much a small gesture matters.'],
  ['Tell me about a time when you wore formal clothes.',
    'Kể về một lần bạn mặc trang phục trang trọng', 3,
    'I would like to talk about my cousin\'s wedding last year, where I wore a suit for only the second time in my life. I had to borrow it from my uncle because buying one seemed wasteful for a single day, and it was slightly too large in the shoulders. I remember feeling extremely uncomfortable for the first hour, mainly because it was thirty-two degrees outside and the jacket was made of wool. But I also noticed that I behaved slightly differently: I stood straighter and I was more careful about how I spoke. Whether formal clothes are still important today is debatable. In my industry nobody wears a tie, and I think that is sensible. However, at events like weddings or funerals, dressing formally is a way of showing that the occasion matters more than your own comfort. That is why I would still do it, even though I would happily never wear a wool jacket in summer again. I have since bought a lighter suit of my own, which was a sensible investment for a country as hot as mine, and I no longer have to borrow anything.'],
  ['Tell me about some interesting information that you learned recently.',
    'Kể về một thông tin thú vị bạn mới biết', 4,
    'I would like to talk about something I read recently about how trees in a forest are connected underground through fungal networks, and can apparently transfer nutrients to each other. I found it in a science article that a colleague shared, and at first I assumed it was exaggerated, because it sounded almost like a story. So I looked for the original research, and the basic finding does seem to be accepted, although scientists disagree about how significant it is. What interested me was that it changes how you picture a forest: not a collection of individual trees competing, but something closer to a community. I have mentioned it to several people since. On whether we should check information before sharing it, I would say absolutely yes, and my own experience is the reason. The version circulating on social media was far more dramatic than the actual research, and if I had simply shared that, I would have been spreading something misleading without meaning to. If I had simply shared the dramatic version, I would have been spreading something misleading without meaning to. That experience has made me check the original source before passing anything on, which takes two minutes and saves a great deal of embarrassment.'],
];

/** UUID tiền định để chạy lại script không sinh bản ghi trùng. */
function idOf(index) {
  return 'a8000000-0000-4000-8000-' + String(index + 1).padStart(12, '0');
}

function buildDoc(index, entry) {
  const [question, vietnamese, hot, sample] = entry;
  const id = idOf(index);
  const title = `${question} (${vietnamese})`;

  return {
    _id: id,
    questionSetId: id,
    revision: NumberInt(1),
    schemaVersion: NumberInt(1),
    partId: PART_ID,
    taskTypeCode: TASK_TYPE,
    title: title,
    instructions: 'Chuẩn bị 1 phút, sau đó nói trong 2 phút (khoảng 180–240 từ).',
    accessLevel: 'FREE',
    stimulus: null,
    sections: [],
    items: [{
      id: 'item_1',
      sequenceNo: NumberInt(1),
      prompt: { format: 'PLAIN_TEXT', value: title },
      responseType: 'AUDIO_RECORDING',
      required: true,
      maxScore: ITEM_SCORE,
      options: [],
      leftItems: [],
      rightItems: [],
      // prepSeconds / responseSeconds là hai khoá RecordingRenderer đọc.
      // minWords / maxWords để giao diện hiện badge "180–240 từ".
      constraints: {
        prepSeconds: PREP_SECONDS,
        responseSeconds: RESPONSE_SECONDS,
        minWords: 180,
        maxWords: 240,
      },
      rubricCode: 'APTIS_SPEAKING',
      answerKey: null,
      // Bài nói mẫu cho học viên tham khảo
      explanation: { format: 'PLAIN_TEXT', value: sample },
    }],
    assets: [],
    settings: {
      shuffleOptions: false,
      shuffleItems: false,
      maxAudioPlays: null,
      showAnswerAfterEachItem: false,
      allowReview: true,
    },
    scoring: { strategy: 'RUBRIC', partialCredit: true, maxScore: ITEM_SCORE },
    createdAt: new Date(),
    updatedAt: new Date(),
  };
}

let count = 0;
TOPICS.forEach(function (entry, index) {
  const doc = buildDoc(index, entry);
  target.question_set_documents.replaceOne({ _id: doc._id }, doc, { upsert: true });
  count++;
  print('  ' + String(index + 1).padStart(2, ' ') + '. ' +
    '🔥'.repeat(entry[2]) + ' ' + entry[0]);
});

print('---');
print('Đã ghi ' + count + ' đề Speaking Part 4.');
print('Tổng document Part 4 = ' + target.question_set_documents.countDocuments({ partId: PART_ID }));
